mapper.select:
select p.product_id, p.product_code, p.product_name, p.spec, p.category_id, c.category_name,
       p.supplier_id, s.supplier_name, p.purchase_price, p.sale_price, p.stock_qty, p.purchase_time,
       p.intro, p.del_flag, p.create_by, p.create_time, p.update_by, p.update_time, p.remark,
        as stock_status,
       (select count(1) from pms_device d where d.product_id = p.product_id) as device_count
from pms_product p
left join pms_category c on c.category_id = p.category_id
left join pms_supplier s on s.supplier_id = p.supplier_id

    p.del_flag = '0'
    AND p.product_name like concat('%', #{productName}, '%')
    AND p.product_code like concat('%', #{productCode}, '%')
    AND p.spec like concat('%', #{spec}, '%')
    AND p.supplier_id = #{supplierId}
    AND p.category_id = #{categoryId}
    AND p.stock_qty >= #{stockMin}
    AND p.stock_qty <= #{stockMax}
    AND p.sale_price >= #{salePriceMin}
    AND p.sale_price <= #{salePriceMax}
    AND p.purchase_time >= #{beginPurchaseTime}
    AND p.purchase_time <= #{endPurchaseTime}
    AND p.stock_qty <= 0
    AND p.stock_qty > 0 AND p.stock_qty < ifnull(#{warnThreshold}, 5)
    AND p.stock_qty >= ifnull(#{warnThreshold}, 5)
    AND p.purchase_time >= #{params.beginTime}
    AND p.purchase_time <= #{params.endTime}

order by p.product_id desc

mapper.update:
update pms_product
product_name = #{productName}, spec = #{spec}, category_id = #{categoryId}, supplier_id = #{supplierId}, purchase_price = #{purchasePrice}, sale_price = #{salePrice}, stock_qty = #{stockQty}, purchase_time = #{purchaseTime}, intro = #{intro}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where product_id = #{productId}
